<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api/client'
import type { ChangeRequest, ChangeRequestStatus, ModuleItem, StageTarget, Timeline, User } from '../api/types'
import { formatDateTime } from '../utils/format'
import { useAuthStore } from '../stores/auth'
import ModuleFormDialog from '../components/ModuleFormDialog.vue'
const id=Number(useRoute().params.id); const router=useRouter(); const auth=useAuthStore(); const project=ref<Timeline>(); const members=ref<User[]>([]); const modules=ref<ModuleItem[]>([]); const stageTargets=ref<StageTarget[]>([]); const available=ref<User[]>([]); const requests=ref<ChangeRequest[]>([]); const moduleDialog=ref(false); const targetDialog=ref(false); const editingModule=ref<ModuleItem|null>(null)
const projectForm=reactive({name:'',code:'',description:'',planStart:'',planEnd:''}); const targetForm=reactive({id:0,name:'',description:'',targetDate:'',hasMetric:false,metricName:'',metricUnit:'',metricTarget:undefined as number|undefined,metricCurrent:undefined as number|undefined})
const currentMember=computed(()=>members.value.find(m=>m.id===auth.user?.id)); const canManage=computed(()=>auth.isAdmin||currentMember.value?.projectRole==='PM')
async function load(){try{const value=await api<Timeline>('GET',`/projects/${id}/timeline`);project.value=value;stageTargets.value=value.stageTargets||[];Object.assign(projectForm,{name:value.name,code:value.code,description:value.description||'',planStart:value.planStart||'',planEnd:value.planEnd||''});members.value=await api('GET',`/projects/${id}/members`);modules.value=await api('GET',`/projects/${id}/modules`);requests.value=await api<ChangeRequest[]>('GET',`/projects/${id}/change-requests`);if(canManage.value)available.value=await api('GET',`/projects/${id}/users`,undefined,{scope:'available'})}catch(e){ElMessage.error((e as Error).message)}}
async function saveProject(){if(!projectForm.name.trim()||!projectForm.code.trim()||!projectForm.planStart){ElMessage.warning('请填写项目名称、项目代号和项目开始日期');return}if(projectForm.planEnd&&projectForm.planEnd<projectForm.planStart){ElMessage.warning('项目完成日期不能早于开始日期');return}try{await api('PUT',`/projects/${id}`,projectForm);ElMessage.success('项目信息已保存');await load()}catch(e){ElMessage.error((e as Error).message)}}
async function addMember(userId:number){try{await api('POST',`/projects/${id}/members`,{userId});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function removeMember(user:User){try{await ElMessageBox.confirm(`确认移出 ${user.name}？`);await api('DELETE',`/projects/${id}/members/${user.id}`);await load()}catch(e){if(e!=='cancel')ElMessage.error((e as Error).message)}}
async function transfer(user:User){try{await ElMessageBox.confirm(`确认将项目经理转交给 ${user.name}？`);await api('PUT',`/projects/${id}/pm`,{userId:user.id});await load()}catch(e){if(e!=='cancel')ElMessage.error((e as Error).message)}}
function openCreateModule(){editingModule.value=null;moduleDialog.value=true}
function editModule(item:ModuleItem){editingModule.value=item;moduleDialog.value=true}
async function deleteModule(item:ModuleItem){try{await ElMessageBox.confirm(`确认删除模块「${item.name}」？含节点的模块不能删除。`,'删除模块',{type:'warning'})}catch{return}try{await api<void>('DELETE',`/modules/${item.id}`);ElMessage.success('模块已删除');await load()}catch(e){ElMessage.error((e as Error).message)}}
function openCreateTarget(){Object.assign(targetForm,{id:0,name:'',description:'',targetDate:project.value?.planStart||'',hasMetric:false,metricName:'',metricUnit:'',metricTarget:undefined,metricCurrent:undefined});targetDialog.value=true}
function editTarget(item:StageTarget){Object.assign(targetForm,{id:item.id,name:item.name,description:item.description||'',targetDate:item.targetDate,hasMetric:item.metricTarget!=null||!!item.metricName,metricName:item.metricName||'',metricUnit:item.metricUnit||'',metricTarget:item.metricTarget,metricCurrent:item.metricCurrent});targetDialog.value=true}
// 量化指标是可选的：不填就是原来的日期型里程碑；填了必须给出指标名称和大于 0 的目标值
async function saveTarget(){
  if(!targetForm.name.trim()||!targetForm.targetDate){ElMessage.warning('请填写目标名称和目标日期');return}
  const metric={metricName:null as string|null,metricUnit:null as string|null,metricTarget:null as number|null,metricCurrent:null as number|null}
  if(targetForm.hasMetric){
    if(!targetForm.metricName.trim()){ElMessage.warning('请填写指标名称');return}
    if(!targetForm.metricTarget||targetForm.metricTarget<=0){ElMessage.warning('目标值必须大于 0');return}
    metric.metricName=targetForm.metricName.trim(); metric.metricUnit=targetForm.metricUnit.trim()||null
    metric.metricTarget=targetForm.metricTarget; metric.metricCurrent=targetForm.metricCurrent??0
  }
  try{const payload={name:targetForm.name,description:targetForm.description,targetDate:targetForm.targetDate,...metric};if(targetForm.id)await api('PUT',`/stage-targets/${targetForm.id}`,payload);else await api('POST',`/projects/${id}/stage-targets`,payload);targetDialog.value=false;ElMessage.success(targetForm.id?'阶段性目标已更新':'阶段性目标已创建');await load()}catch(e){ElMessage.error((e as Error).message)}
}
async function deleteTarget(item:StageTarget){try{await ElMessageBox.confirm(`确认删除阶段性目标“${item.name}”？`);await api('DELETE',`/stage-targets/${item.id}`);await load()}catch(e){if(e!=='cancel')ElMessage.error((e as Error).message)}}
// 模块变更申请：PM 审批通过后服务端立即改模块；驳回必须填原因；申请人可撤回自己待审批的申请
const REQUEST_STATUS_LABELS:Record<ChangeRequestStatus,string>={PENDING:'待审批',APPROVED:'已通过',REJECTED:'已驳回',CANCELLED:'已撤回'}
const REQUEST_STATUS_TYPES:Record<ChangeRequestStatus,'warning'|'success'|'danger'|'info'|'primary'|''>={PENDING:'warning',APPROVED:'success',REJECTED:'danger',CANCELLED:'info'}
const statusLabel=(status:ChangeRequestStatus)=>REQUEST_STATUS_LABELS[status]
const statusType=(status:ChangeRequestStatus)=>REQUEST_STATUS_TYPES[status]
// 归档项目里审批/撤回都会被服务端拒绝，按钮同步隐藏，避免点了才报错
const canHandleRequest=computed(()=>project.value?.status!=='ARCHIVED')
async function approveRequest(row:ChangeRequest){
  try{await ElMessageBox.confirm(`确认通过「${row.moduleName}」的变更申请？通过后立即生效。`,'审批通过')}catch{return}
  try{await api('PUT',`/change-requests/${row.id}/decision`,{approved:true});ElMessage.success('已通过并生效');await load()}catch(e){ElMessage.error((e as Error).message)}
}
async function rejectRequest(row:ChangeRequest){
  let remark=''
  try{const result=await ElMessageBox.prompt('驳回原因会展示给申请人','驳回申请',{inputType:'textarea',inputPlaceholder:'请填写驳回原因'});remark=(result.value||'').trim()}catch{return}
  if(!remark){ElMessage.warning('请填写驳回原因');return}
  try{await api('PUT',`/change-requests/${row.id}/decision`,{approved:false,remark});ElMessage.success('已驳回');await load()}catch(e){ElMessage.error((e as Error).message)}
}
async function cancelRequest(row:ChangeRequest){
  try{await ElMessageBox.confirm('确认撤回这条变更申请？')}catch{return}
  try{await api('POST',`/change-requests/${row.id}/cancel`);ElMessage.success('已撤回');await load()}catch(e){ElMessage.error((e as Error).message)}
}
async function archive(){try{if(project.value?.status==='ARCHIVED')await api('POST',`/projects/${id}/unarchive`);else await api('POST',`/projects/${id}/archive`);await load()}catch(e){ElMessage.error((e as Error).message)}} onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>项目设置</h1><p>基本信息、阶段性目标、成员与模块负责人。</p></div><el-button @click="router.push(`/projects/${id}/timeline`)">返回时间线</el-button></header><el-alert v-if="!canManage" title="当前账号只有查看权限" type="info" :closable="false" style="margin-bottom:18px"/>
<section class="surface" style="margin-bottom:18px"><h2>基本信息</h2><el-form label-position="top" :disabled="!canManage||project?.status==='ARCHIVED'"><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><el-form-item label="项目名称"><el-input v-model="projectForm.name"/></el-form-item><el-form-item label="项目代号"><el-input v-model="projectForm.code"/></el-form-item></div><el-form-item label="描述"><el-input v-model="projectForm.description" type="textarea"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><el-form-item label="项目开始日期（必填）" required><el-date-picker v-model="projectForm.planStart" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="项目完成日期（可选）"><el-date-picker v-model="projectForm.planEnd" value-format="YYYY-MM-DD" clearable style="width:100%"/></el-form-item></div><el-button type="primary" @click="saveProject">保存</el-button><el-button :type="project?.status==='ARCHIVED'?'success':'danger'" plain @click="archive">{{project?.status==='ARCHIVED'?'恢复项目':'归档项目'}}</el-button></el-form></section>
<section class="surface" style="margin-bottom:18px"><div style="display:flex;justify-content:space-between"><h2>项目成员</h2><el-dropdown v-if="canManage&&available.length" @command="addMember"><el-button type="primary" plain>添加成员</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="user in available" :key="user.id" :command="user.id">{{user.name}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><el-table :data="members"><el-table-column prop="name" label="成员"/><el-table-column prop="globalRole" label="全局角色"/><el-table-column prop="projectRole" label="项目职务"/><el-table-column label="操作"><template #default="scope"><el-button v-if="canManage&&scope.row.projectRole!=='PM'" link type="primary" @click="transfer(scope.row)">设为 PM</el-button><el-button v-if="canManage&&scope.row.projectRole!=='PM'" link type="danger" @click="removeMember(scope.row)">移出</el-button></template></el-table-column></el-table></section>
<section class="surface" style="margin-bottom:18px"><div style="display:flex;justify-content:space-between"><div><h2>项目阶段性目标</h2><p class="muted">记录项目在特定日期需要达到的关键目标，与功能模块独立；可附一个可选的量化指标（当前值 / 目标值）用来看达成多少，不做评分与周期管理。</p></div><el-button v-if="canManage&&project?.status!=='ARCHIVED'" type="primary" plain @click="openCreateTarget">新建目标</el-button></div><el-table :data="stageTargets"><el-table-column prop="name" label="目标"/><el-table-column prop="description" label="说明"/><el-table-column label="量化指标" width="190"><template #default="scope"><template v-if="scope.row.metricName">{{scope.row.metricName}}：{{scope.row.metricCurrent??0}}/{{scope.row.metricTarget}}{{scope.row.metricUnit?(' '+scope.row.metricUnit):''}}</template><span v-else class="muted">—</span></template></el-table-column><el-table-column label="达成度" width="90"><template #default="scope"><template v-if="scope.row.progress!=null">{{scope.row.progress}}%</template><span v-else class="muted">—</span></template></el-table-column><el-table-column prop="targetDate" label="目标日期" width="140"/><el-table-column v-if="canManage&&project?.status!=='ARCHIVED'" label="操作" width="130"><template #default="scope"><el-button link type="primary" @click="editTarget(scope.row)">编辑</el-button><el-button link type="danger" @click="deleteTarget(scope.row)">删除</el-button></template></el-table-column></el-table></section>
<section class="surface" style="margin-bottom:18px"><div><h2>模块变更申请</h2><p class="muted">普通成员改别人的模块时，在模块页点「申请变更模块」提交，这里的申请由项目经理审批，通过后自动生效。</p></div><el-table :data="requests" empty-text="暂无变更申请"><el-table-column prop="moduleName" label="模块" width="150"/><el-table-column label="申请内容" min-width="220"><template #default="scope"><div>{{scope.row.name}}</div><div class="muted" style="font-size:12px">负责人 {{scope.row.ownerName||'—'}}</div></template></el-table-column><el-table-column prop="requesterName" label="申请人" width="100"/><el-table-column label="状态" width="90"><template #default="scope"><el-tag :type="statusType(scope.row.status as ChangeRequestStatus)" size="small">{{statusLabel(scope.row.status as ChangeRequestStatus)}}</el-tag></template></el-table-column><el-table-column prop="reason" label="申请说明" min-width="160" show-overflow-tooltip/><el-table-column prop="decisionRemark" label="审批意见" min-width="140" show-overflow-tooltip/><el-table-column label="提交时间" width="160"><template #default="scope">{{formatDateTime(scope.row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><template v-if="scope.row.status==='PENDING'&&canManage&&canHandleRequest"><el-button link type="primary" @click="approveRequest(scope.row)">通过</el-button><el-button link type="danger" @click="rejectRequest(scope.row)">驳回</el-button></template><el-button v-if="scope.row.status==='PENDING'&&canHandleRequest&&scope.row.requestedBy===auth.user?.id" link @click="cancelRequest(scope.row)">撤回</el-button></template></el-table-column></el-table></section>
<section class="surface"><div style="display:flex;justify-content:space-between"><h2>模块</h2><el-button v-if="canManage&&project?.status!=='ARCHIVED'" type="primary" plain @click="openCreateModule">新建模块</el-button></div><el-table :data="modules"><el-table-column prop="name" label="模块"/><el-table-column prop="ownerName" label="负责人"/><el-table-column prop="nodeCount" label="节点数"/><el-table-column prop="progress" label="进度"/><el-table-column v-if="canManage&&project?.status!=='ARCHIVED'" label="操作" width="130"><template #default="scope"><el-button link type="primary" @click="editModule(scope.row)">编辑</el-button><el-button link type="danger" @click="deleteModule(scope.row)">删除</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="targetDialog" :title="targetForm.id?'编辑阶段性目标':'新建阶段性目标'" width="560"><el-form label-position="top"><el-form-item label="目标名称" required><el-input v-model="targetForm.name"/></el-form-item><el-form-item label="目标说明"><el-input v-model="targetForm.description" type="textarea"/></el-form-item><el-form-item label="量化指标（可选）"><el-checkbox v-model="targetForm.hasMetric">用「当前值 / 目标值」看达成多少</el-checkbox><p class="muted" style="margin:4px 0 0;font-size:12px">不填就是按日期判断的里程碑；填了由系统自动算达成度，超额完成按 100% 显示。</p></el-form-item><template v-if="targetForm.hasMetric"><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><el-form-item label="指标名称" required><el-input v-model="targetForm.metricName" maxlength="100" placeholder="例如：上线模块数"/></el-form-item><el-form-item label="单位"><el-input v-model="targetForm.metricUnit" maxlength="20" placeholder="例如：个、万元"/></el-form-item></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><el-form-item label="目标值" required><el-input-number v-model="targetForm.metricTarget" :min="0" :step="1" :precision="2" style="width:100%"/></el-form-item><el-form-item label="当前值"><el-input-number v-model="targetForm.metricCurrent" :min="0" :step="1" :precision="2" style="width:100%"/></el-form-item></div></template><el-form-item label="目标日期" required><el-date-picker v-model="targetForm.targetDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="targetDialog=false">取消</el-button><el-button type="primary" @click="saveTarget">{{targetForm.id?'保存':'创建'}}</el-button></template></el-dialog>
<ModuleFormDialog v-model="moduleDialog" :project-id="id" :module="editingModule" :members="members" :default-owner-id="currentMember?.id||0" @saved="load" /></div></template>
